<summary>⚡ Suggested optimization sketch</summary>

```diff
 export function buildModuleGraph(
   fileToModulesMap: ViteDevServer['moduleGraph']['fileToModulesMap']
 ): ModuleGraph {
   const moduleGraph: ModuleGraph = new Map();
   const moduleNodeMap = new WeakMap<object, ModuleNode>();
+  const fileByViteNode = new WeakMap<ViteModuleNode, string>();
+
+  for (const [filePath, viteModuleSet] of fileToModulesMap.entries()) {
+    for (const viteModuleNode of viteModuleSet) {
+      fileByViteNode.set(viteModuleNode, filePath);
+    }
+  }

-  const getModuleFileFromMap = (viteModuleNode: { ... }): string | undefined => {
-    for (const [filePath, viteModuleSet] of fileToModulesMap.entries()) {
-      if (viteModuleSet.has(viteModuleNode as ViteModuleNode)) {
-        return filePath;
-      }
-    }
-  };
+  const getModuleFileFromMap = (viteModuleNode: ViteModuleNode): string | undefined =>
+    fileByViteNode.get(viteModuleNode);
